// Master Aggregator & Normalizer for Remotive, RemoteOK, and Y Combinator
const normalized = [];

// 1. Process Remotive
try {
  const remotiveData = $("1. Fetch Remotive Jobs").first().json;
  const rJobs = remotiveData.jobs || [];
  for (const j of rJobs) {
    normalized.push({
      title: j.title || '',
      company_name: j.company_name || 'Startup',
      url: j.url || '',
      location: j.candidate_required_location || 'Remote / Global',
      description: (j.description || '').replace(/<[^>]*>?/gm, '').slice(0, 1000),
      source: 'Remotive'
    });
  }
} catch (e) {}

// 2. Process RemoteOK
try {
  const remoteokData = $("2. Fetch RemoteOK Jobs").all();
  for (const item of remoteokData) {
    const j = item.json;
    if (j && j.position && j.url) {
      normalized.push({
        title: j.position || '',
        company_name: j.company || 'Startup',
        url: j.url || '',
        location: j.location || '100% Remote',
        description: (j.description || '').replace(/<[^>]*>?/gm, '').slice(0, 1000),
        source: 'RemoteOK'
      });
    }
  }
} catch (e) {}

// 3. Process Y Combinator
try {
  const ycData = $("3. Fetch Y Combinator Jobs").first().json;
  const hits = ycData.hits || [];
  for (const h of hits) {
    if (h.title) {
      normalized.push({
        title: h.title,
        company_name: 'YC Backed Startup',
        url: h.url || `https://news.ycombinator.com/item?id=${h.objectID}`,
        location: 'Remote / Global',
        description: (h.story_text || h.comment_text || h.title || '').slice(0, 1000),
        source: 'Y Combinator'
      });
    }
  }
} catch (e) {}

// 4. Pre-filter by keywords (APM, PM, Growth, Founder's Office, GTM, Analyst)
const validKeywords = ['product', 'apm', 'associate', 'growth', 'gtm', 'founder', 'analyst', 'strategy', 'operations', 'intern'];
const excludeSenior = ['director', 'vice president', 'chief ', 'head of', 'lead engineer', 'staff engineer', 'principal'];

const filtered = normalized.filter(j => {
  const t = j.title.toLowerCase();
  const isMatch = validKeywords.some(k => t.includes(k));
  const isTooSenior = excludeSenior.some(k => t.includes(k));
  return isMatch && !isTooSenior;
});

// 5. Deduplicate by title + company
const seen = new Set();
const unique = [];
for (const j of filtered) {
  const key = `${j.company_name.toLowerCase()} - ${j.title.toLowerCase()}`;
  if (!seen.has(key)) {
    seen.add(key);
    unique.push(j);
  }
}

// Batch top 10 unique roles per 6h run
return unique.slice(0, 10).map(job => ({ json: job }));

